    if (!(await ping())) return { ok: false, offline: true, msg: offMsg() };
    var on = of(readSt()), mine = arr(M.data.names).some(function (x) { return x.kind === kind && x.name === name; });
    var vars = { '名': name, '种': kind === '导演' ? '导演署名' : '男优艺名' };
    try {
